const transmissionLinesLayer = L.geoJSON(TRANSMISSION_LINES_GEOJSON, {
  style: f => ({
    color: '#facc15',
    weight: (f.properties.VOLTAGE >= 500) ? 3 : 2,
    opacity: 0.6,
    dashArray: (f.properties.OWNER === 'NOT AVAILABLE') ? '4,4' : null
  }),
  onEachFeature: (feature, layer) => {
    const p = feature.properties;
    const owner = (p.OWNER && p.OWNER !== 'NOT AVAILABLE') ? p.OWNER : 'Owner not available in source data';
    const subs = (p.SUB_1 && p.SUB_2) ? `${p.SUB_1} \u2192 ${p.SUB_2}<br>` : '';
    layer.bindTooltip(`
      \u26a1 <b>${p.VOLTAGE}kV transmission line</b><br>
      ${subs}Owner: ${owner}<br>
      <div style="color:#94a3b8;font-size:11px;margin-top:4px;">Source: HIFLD (DHS), public use</div>
    `, { sticky: true, className: 'dark-tooltip' });
  }
});

const substationsLayer = L.geoJSON(SUBSTATIONS_GEOJSON, {
  pointToLayer: (feature, latlng) => L.circleMarker(latlng, {
    radius: 5,
    color: '#ca8a04',
    fillColor: '#fde047',
    fillOpacity: 0.9,
    weight: 2
  }),
  onEachFeature: (feature, layer) => {
    const p = feature.properties;
    layer.bindTooltip(`
      \ud83d\udd0c <b>${p.NAME}</b> substation<br>
      ${p.CITY}, ${p.COUNTY} County<br>
      Max voltage: ${p.MAX_VOLT}kV \u00b7 ${p.LINES} connected lines<br>
      <div style="color:#94a3b8;font-size:11px;margin-top:4px;">Source: HIFLD (DHS), public use</div>
    `, { sticky: true, className: 'dark-tooltip' });
  }
});

// ═══════════════════════════════════════════════════════════════
//  GRID PROXIMITY WATCH LIST — Predictive Layer
//  Methodology: for every tracked municipality NOT already flagged
//  as a CWA case, CWA alumni, or an active data-center case, AND
//  whose planning services are contracted out (not in-house city/
//  township staff — matching the governance profile every confirmed
//  case in this tracker shares), compute:
//    - straight-line distance to the nearest 345kV+ substation
//    - that substation's connected-line count (LINES field), used
//      as a rough proxy for grid capacity/importance — HIFLD does
//      not publish actual available interconnection capacity
//  Score = sub_lines / (1 + distance_mi/3), ranked descending.
//  Calibration: the 4 confirmed sites already on this map (Allen
//  Park, Saline Twp, Washington Twp, Lyon Twp) sit 1.8-8.3mi from
//  their nearest 345kV+ substation, which set the working radius.
//  This is a heuristic screen, not a finding — proximity to grid
//  capacity and a contracted planner is a precondition data centers
//  need, not evidence any specific developer or firm is active
//  there. Top 30 shown. Computed 2026-09-16 from HIFLD + this
//  tracker's own municipality data.
// ═══════════════════════════════════════════════════════════════

