const gridWatchLayer = L.layerGroup();
const GW_SCORES = GRID_WATCH_LIST.map(w => w.score);
const GW_MAX = Math.max(...GW_SCORES);
const GW_MIN = Math.min(...GW_SCORES);

// Visual encoding so rank is readable at a glance, not just on hover:
// bigger + darker/more saturated red = higher grid-proximity score.
// Rank number is a permanent on-map label (not just in the tooltip).
function gwRadius(score) {
  const t = (score - GW_MIN) / ((GW_MAX - GW_MIN) || 1);
  return 6 + t * 12; // 6px (lowest) to 18px (highest)
}
function gwColor(score) {
  const t = (score - GW_MIN) / ((GW_MAX - GW_MIN) || 1);
  // light salmon (#fecaca) at low end -> deep red (#7f1d1d) at high end
  const stops = [
    [254, 202, 202], [239, 68, 68], [127, 29, 29]
  ];
  const seg = t < 0.5 ? 0 : 1;
  const localT = t < 0.5 ? t / 0.5 : (t - 0.5) / 0.5;
  const a = stops[seg], b = stops[seg + 1];
  const r = Math.round(a[0] + (b[0] - a[0]) * localT);
  const g = Math.round(a[1] + (b[1] - a[1]) * localT);
  const bch = Math.round(a[2] + (b[2] - a[2]) * localT);
  return `rgb(${r},${g},${bch})`;
}

GRID_WATCH_LIST.forEach((w, idx) => {
  const rank = idx + 1;
  const radius = gwRadius(w.score);
  const fill = gwColor(w.score);
  const marker = L.circleMarker([w.lat, w.lng], {
    radius: radius,
    color: '#fff',
    weight: 1,
    fillColor: fill,
    fillOpacity: 0.85
  });
  marker.bindTooltip(`${rank}`, {
    permanent: true,
    direction: 'center',
    className: 'grid-watch-rank-label'
  });
  marker.bindPopup(`
    \ud83c\udfaf <b>#${rank} ${w.municipality}</b>, ${w.county} County (${w.type})<br>
    Planning: ${w.firm} (${w.employment_type})<br>
    Nearest 345kV+ substation: <b>${w.sub_name}</b> (${w.sub_city}) \u2014 ${w.sub_lines} lines, ${w.sub_dist_mi}mi away<br>
    Nearest 345kV+ line: ${w.line_dist_mi}mi<br>
    Grid proximity score: <b>${w.score}</b> (higher = closer to a bigger substation)<br>
    <div style="color:#94a3b8;font-size:11px;margin-top:4px;max-width:260px;">Heuristic screen only \u2014 not a confirmed case. Flags municipalities with contracted (non-in-house) planning near high-capacity grid infrastructure, the same profile every confirmed case on this map shares.</div>
  `, { className: 'dark-tooltip' });
  marker.addTo(gridWatchLayer);
});

