// ═══════════════════════════════════════════════════════════════
//  HELPERS
// ═══════════════════════════════════════════════════════════════

function getFirmColor(m) {
  if (m.cwa_alumni) return FIRMS["CWA Alumni / In-House"].color;
  return (FIRMS[m.firm] || FIRMS["Unknown"]).color;
}

function buildPopup(m) {
  const color = getFirmColor(m);

  let flags = '';
  if (m.cwa_flag) flags += `<span class="popup-flag-cwa">⚠ CWA FLAGGED</span> `;
  if (m.cwa_alumni) flags += `<span class="popup-flag-alumni">🔶 CWA Alumni</span> `;
  if (m.data_center_case) flags += `<span class="popup-flag-dc">⚡ Data Center Case</span> `;
  if (m.status === 'terminated') flags += `<span class="popup-flag-terminated">CONTRACT TERMINATED</span> `;

  const plannerHtml = m.planner_name
    ? `<span class="bold">${m.planner_name}</span><br><span style="color:#94a3b8;font-size:11px">${m.planner_title || ''}</span>`
    : `<span style="color:#57534e;font-style:italic">Unknown — needs research</span>`;

  const historyHtml = m.work_history
    ? m.work_history
    : `<span style="color:#57534e;font-style:italic">Not documented</span>`;

  const dcBox = m.data_center_case
    ? `<div class="popup-dc-box"><div class="popup-notes-label">⚡ Data Center Case</div>${m.data_center_notes}</div>`
    : '';

  const notesBox = m.notes
    ? `<div class="popup-notes"><div class="popup-notes-label">Research Notes</div>${m.notes}</div>`
    : '';

  const meetingDocsBox = (m.meeting_docs && (m.meeting_docs.links || m.meeting_docs.monitor_status))
    ? `<div class="popup-meeting-docs">
         <div class="popup-notes-label" style="color:#4ade80">📋 Meeting Documents</div>
         ${(m.meeting_docs.links || []).map(l => `<a href="${l.url}" target="_blank" rel="noopener">${l.label}</a>`).join(' · ')}
         ${m.meeting_docs.monitor_status ? `<div class="popup-meeting-monitor">🔔 ${m.meeting_docs.monitor_status}${m.meeting_docs.monitor_checked ? ` <span style="color:#3f6b4f">(last checked ${m.meeting_docs.monitor_checked})</span>` : ''}</div>` : ''}
       </div>`
    : '';

  const unknownBanner = !m.planner_name
    ? `<div class="unknown-banner">📋 Planner info missing — check municipal website or submit FOIA</div>`
    : '';

  const srcHtml = m.sources && m.sources.length
    ? `<div class="popup-sources">📚 Sources: ${m.sources.join(' · ')}</div>`
    : '';

  return `
    <div>
      <div class="popup-header">
        <div class="popup-muni-name">${m.municipality}</div>
        <div class="popup-meta">
          <span class="popup-type-badge">${m.type}</span>
          <span>${m.county} County</span>
          ${flags}
        </div>
      </div>
      <div class="popup-body">
        <div class="popup-row">
          <span class="popup-row-label">Planner</span>
          <span class="popup-row-value">${plannerHtml}</span>
        </div>
        <div class="popup-row">
          <span class="popup-row-label">Firm</span>
          <span class="popup-row-value">
            <span class="popup-firm-color" style="background:${color}"></span>
            ${m.firm}
          </span>
        </div>
        <div class="popup-row">
          <span class="popup-row-label">Type</span>
          <span class="popup-row-value">${m.employment_type || '—'}</span>
        </div>
        <div class="popup-row">
          <span class="popup-row-label">Status</span>
          <span class="popup-row-value" style="color:${m.status==='active'?'#4ade80':m.status==='terminated'?'#ef4444':'#94a3b8'}">
            ${m.status.charAt(0).toUpperCase() + m.status.slice(1)}
          </span>
        </div>
        <div class="popup-row">
          <span class="popup-row-label">History</span>
          <span class="popup-row-value">${historyHtml}</span>
        </div>
        ${dcBox}
        ${notesBox}
        ${meetingDocsBox}
        ${unknownBanner}
        ${srcHtml}
      </div>
    </div>
  `;
}

// ═══════════════════════════════════════════════════════════════
//  DRAW MARKERS
// ═══════════════════════════════════════════════════════════════

const markerRefs = {};

function drawMarkers(data) {
  markersLayer.clearLayers();
  data.forEach(m => {
    const color = getFirmColor(m);
    const isCWA = m.cwa_flag;
    const isAlumni = m.cwa_alumni;
    const hasDC = m.data_center_case;
    // Unincorporated / confirmed-unzoned municipalities (firm "N/A") get a distinct
    // square "no zoning" icon instead of the usual circular data-point dot, so they
    // read as a different category at a glance rather than blending in with —or
    // looking like missing data among— the researched entries.
    const isUnzoned = m.firm === 'N/A';

    let marker;
    if (isUnzoned) {
      marker = L.marker([m.lat, m.lng], {
        icon: L.divIcon({
          html: `<div style="font-size:9px;color:white;background:#78716c;border-radius:4px;width:15px;height:15px;display:flex;align-items:center;justify-content:center;font-weight:900;border:1px solid rgba(255,255,255,0.4)" title="No zoning / unincorporated">⊘</div>`,
          className: '',
          iconSize: [15, 15],
          iconAnchor: [8, 8]
        })
      });
    } else {
      marker = L.circleMarker([m.lat, m.lng], {
        radius: hasDC ? 12 : (isCWA || isAlumni ? 10 : 8),
        fillColor: color,
        color: isCWA ? '#b91c1c' : (isAlumni ? '#92400e' : color),
        weight: isCWA ? 3 : (hasDC ? 2.5 : 1.5),
        fillOpacity: 0.85,
        opacity: 1
      });
    }

    marker.bindPopup(buildPopup(m), { maxWidth: 340 });

    if (!isUnzoned) {
      marker.on('mouseover', function() {
        this.setStyle({ radius: (this.options.radius + 3), fillOpacity: 1 });
      });
      marker.on('mouseout', function() {
        this.setStyle({ radius: (this.options.radius - 3), fillOpacity: 0.85 });
      });
    }
    marker.on('click', function() {
      highlightListItem(m.id);
    });

    // Pulsing effect for active data center cases
    if (hasDC && m.status === 'active') {
      const pulse = L.circleMarker([m.lat, m.lng], {
        radius: 16,
        fillColor: 'transparent',
        color: '#E53935',
        weight: 2,
        fillOpacity: 0,
        opacity: 0.4,
        className: 'pulse-marker'
      }).addTo(markersLayer);
    }

    // Warning overlay for CWA
    if (isCWA) {
      const warn = L.marker([m.lat, m.lng], {
        icon: L.divIcon({
          html: `<div style="font-size:8px;color:white;background:${m.status==='terminated'?'#78716c':'#E53935'};border-radius:50%;width:14px;height:14px;display:flex;align-items:center;justify-content:center;font-weight:900;border:1px solid rgba(255,255,255,0.3)">${m.status==='terminated'?'✕':'!'}</div>`,
          className: '',
          iconSize: [14, 14],
          iconAnchor: [7, 7]
        }),
        zIndexOffset: 100,
        interactive: false
      }).addTo(markersLayer);
    }

    // On-map badge for data center cases — offset to the bottom-right corner
    // of the marker (anchor pushed negative) so it doesn't collide with the
    // CWA "!"/"✕" badge, which is centered, when a municipality has both flags.
    if (hasDC && !isUnzoned) {
      const dcBadge = L.marker([m.lat, m.lng], {
        icon: L.divIcon({
          html: `<div style="font-size:9px;color:#1a1a1a;background:#fbbf24;border-radius:50%;width:14px;height:14px;display:flex;align-items:center;justify-content:center;font-weight:900;border:1px solid rgba(0,0,0,0.35);box-shadow:0 0 2px rgba(0,0,0,0.5)" title="Data Center Case">⚡</div>`,
          className: '',
          iconSize: [14, 14],
          iconAnchor: [-9, -9]
        }),
        zIndexOffset: 110,
        interactive: false
      }).addTo(markersLayer);
    }

    // On-map badge for DTE Energy builds/proposals — offset to the bottom-left
    // corner so it doesn't collide with the centered CWA badge or the
    // bottom-right Data Center Case badge when a municipality carries multiple flags.
    if (m.dte_flag && !isUnzoned) {
      const dteBadge = L.marker([m.lat, m.lng], {
        icon: L.divIcon({
          html: `<div style="font-size:9px;color:white;background:#0d9488;border-radius:50%;width:14px;height:14px;display:flex;align-items:center;justify-content:center;font-weight:900;border:1px solid rgba(0,0,0,0.35);box-shadow:0 0 2px rgba(0,0,0,0.5)" title="DTE Energy build/proposal">🔌</div>`,
          className: '',
          iconSize: [14, 14],
          iconAnchor: [23, -9]
        }),
        zIndexOffset: 105,
        interactive: false
      }).addTo(markersLayer);
    }

    // On-map badge for BESS (battery energy storage) cases — offset to the
    // top-right corner so it doesn't collide with the centered CWA badge or
    // the bottom-row DC/DTE badges. Hover shows the specific, per-municipality
    // reason (bess_reason) rather than a generic label, since a bare "BESS"
    // icon on its own doesn't explain why a given community has one.
    if (m.bess_flag && !isUnzoned) {
      const bessTitle = (m.bess_reason || 'Battery Energy Storage (BESS) case').replace(/"/g, '&quot;');
      const bessBadge = L.marker([m.lat, m.lng], {
        icon: L.divIcon({
          html: `<div style="font-size:9px;color:white;background:#16a34a;border-radius:50%;width:14px;height:14px;display:flex;align-items:center;justify-content:center;font-weight:900;border:1px solid rgba(0,0,0,0.35);box-shadow:0 0 2px rgba(0,0,0,0.5)" title="${bessTitle}">🔋</div>`,
          className: '',
          iconSize: [14, 14],
          iconAnchor: [-9, 23]
        }),
        zIndexOffset: 107,
        interactive: false
      }).addTo(markersLayer);
    }

    marker.addTo(markersLayer);
    markerRefs[m.id] = marker;
  });
}

// ═══════════════════════════════════════════════════════════════
//  DRAW PLANNER CONNECTION LINES
// ═══════════════════════════════════════════════════════════════

function drawPlannerLines(data) {
  plannerLinesLayer.clearLayers();

  // Group by planner name — exclude placeholder values ("Unknown" and any
  // value starting with "Unknown ") since those aren't a real shared planner,
  // just an absence of data; connecting them creates meaningless clutter.
  const byPlanner = {};
  data.forEach(m => {
    if (!m.planner_name) return;
    if (m.planner_name === 'Unknown' || m.planner_name.startsWith('Unknown ') || m.planner_name.startsWith('Unknown(')) return;
    // "N/A — not a zoned community" is a placeholder shared by every confirmed-unzoned
    // entry, not an actual shared planner — exclude it the same way "Unknown" is excluded.
    if (m.firm === 'N/A' || m.planner_name.startsWith('N/A')) return;
    if (!byPlanner[m.planner_name]) byPlanner[m.planner_name] = [];
    byPlanner[m.planner_name].push(m);
  });

  Object.entries(byPlanner).forEach(([plannerName, munis]) => {
    if (munis.length < 2) return;
    const color = getFirmColor(munis[0]);

    // Draw line between all pairs
    for (let i = 0; i < munis.length; i++) {
      for (let j = i + 1; j < munis.length; j++) {
        const a = munis[i], b = munis[j];
        const line = L.polyline([[a.lat, a.lng], [b.lat, b.lng]], {
          color: color,
          weight: 3,
          opacity: 0.85,
          dashArray: null
        });
        line.bindTooltip(`🔗 Same planner: <b>${plannerName}</b>`, { sticky: true, className: 'dark-tooltip' });
        line.addTo(plannerLinesLayer);
      }
    }
  });
}

// ═══════════════════════════════════════════════════════════════
//  DRAW FIRM NETWORK LINES
// ═══════════════════════════════════════════════════════════════

function drawFirmLines(data) {
  firmLinesLayer.clearLayers();

  // Exclude placeholder/generic firm buckets — "Unknown" (no firm identified),
  // "In-House (City Staff)" (each township's own independent staff, not an
  // actual shared consulting relationship), and "N/A" (confirmed-unzoned
  // communities, not a real firm) aren't real cross-municipality connections;
  // chaining them together across the state is just noise.
  const FIRM_LINE_EXCLUDE = new Set(['Unknown', 'In-House (City Staff)', 'In-House', 'N/A']);
  const byFirm = {};
  data.forEach(m => {
    const firmKey = m.firm;
    if (FIRM_LINE_EXCLUDE.has(firmKey)) return;
    if (!byFirm[firmKey]) byFirm[firmKey] = [];
    byFirm[firmKey].push(m);
  });

  Object.entries(byFirm).forEach(([firmName, munis]) => {
    if (munis.length < 2) return;
    const color = getFirmColor(munis[0]);

    // Sort by longitude, connect sequentially (chain)
    const sorted = [...munis].sort((a, b) => a.lng - b.lng);
    for (let i = 0; i < sorted.length - 1; i++) {
      const a = sorted[i], b = sorted[i + 1];
      L.polyline([[a.lat, a.lng], [b.lat, b.lng]], {
        color: color,
        weight: 1.5,
        opacity: 0.35,
        dashArray: '5, 6'
      })
      .bindTooltip(`〰 Same firm: <b>${firmName}</b>`, { sticky: true, className: 'dark-tooltip' })
      .addTo(firmLinesLayer);
    }
  });
}

// ═══════════════════════════════════════════════════════════════
//  SIDEBAR — FIRM FILTERS
// ═══════════════════════════════════════════════════════════════

let activeFirms = new Set(Object.keys(FIRMS));
let showDCOnly = false;
let showDTEOnly = false;
let showBESSOnly = false;
let currentSearch = '';
let currentSort = 'name';

function setAllFirms(state) {
  document.querySelectorAll('#firm-filters input[type="checkbox"]').forEach(cb => {
    cb.checked = state;
    const firm = cb.getAttribute('data-firm');
    if (state) activeFirms.add(firm);
    else activeFirms.delete(firm);
  });
  refreshMap();
}

function buildFirmFilters() {
  const counts = {};
  MUNICIPALITIES.forEach(m => {
    const f = m.cwa_alumni ? "CWA Alumni / In-House" : (m.firm || "Unknown");
    counts[f] = (counts[f] || 0) + 1;
  });

  const container = document.getElementById('firm-filters');
  container.innerHTML = '';

  // Sort: CWA first, then alphabetical
  const sortedFirms = Object.keys(counts).sort((a, b) => {
    if (a.includes('Carlisle')) return -1;
    if (b.includes('Carlisle')) return 1;
    if (a.includes('Alumni')) return -1;
    if (b.includes('Alumni')) return 1;
    return a.localeCompare(b);
  });

  sortedFirms.forEach(firm => {
    const info = FIRMS[firm] || FIRMS["Unknown"];
    const isCWA = firm.includes('Carlisle');
    const isAlumni = firm.includes('Alumni');

    const row = document.createElement('label');
    row.className = 'filter-row';
    row.innerHTML = `
      <input type="checkbox" checked data-firm="${firm}" />
      <span class="firm-dot" style="background:${info.color}"></span>
      <span class="filter-label">${firm}</span>
      ${isCWA ? '<span class="cwa-badge">⚠ FLAGGED</span>' : ''}
      ${isAlumni ? '<span class="cwa-badge" style="background:#431407;color:#fdba74">Alumni</span>' : ''}
      <span class="filter-count">${counts[firm]}</span>
    `;
    row.querySelector('input').addEventListener('change', e => {
      if (e.target.checked) activeFirms.add(firm);
      else activeFirms.delete(firm);
      refreshMap();
    });
    container.appendChild(row);
  });

  // Legend
  buildLegend(sortedFirms);
}

function buildLegend(firms) {
  const container = document.getElementById('legend-firms');
  container.innerHTML = '';
  firms.forEach(firm => {
    const info = FIRMS[firm] || FIRMS["Unknown"];
    container.innerHTML += `
      <div class="legend-row">
        <div class="legend-dot" style="background:${info.color}"></div>
        <span class="legend-label">${info.short || firm}</span>
      </div>
    `;
  });
}

// ═══════════════════════════════════════════════════════════════
//  SIDEBAR — MUNICIPALITY LIST
// ═══════════════════════════════════════════════════════════════

function buildMuniList(data) {
  const list = document.getElementById('muni-list');
  list.innerHTML = '';

  data.forEach(m => {
    const color = getFirmColor(m);
    const flags = [
      m.cwa_flag ? '⚠' : '',
      m.cwa_alumni ? '🔶' : '',
      m.data_center_case ? '⚡' : '',
      m.dte_flag ? '🔌' : '',
      m.bess_flag ? '🔋' : '',
      m.status === 'terminated' ? '✕' : ''
    ].filter(Boolean).join('');

    const item = document.createElement('div');
    item.className = 'muni-item';
    item.dataset.id = m.id;
    item.innerHTML = `
      <div class="muni-color-bar" style="background:${color};opacity:${m.status==='terminated'?0.4:1}"></div>
      <div class="muni-info">
        <div class="muni-name" style="opacity:${m.status==='terminated'?0.6:1}">${m.municipality}</div>
        <div class="muni-sub">${m.county} Co. · ${m.type} · ${m.planner_name || '❓ planner unknown'}</div>
      </div>
      ${flags ? `<div class="muni-flag">${flags}</div>` : ''}
    `;
    item.addEventListener('click', () => {
      map.setView([m.lat, m.lng], 12);
      const mk = markerRefs[m.id];
      if (mk) mk.openPopup();
      highlightListItem(m.id);
    });
    list.appendChild(item);
  });
}

function highlightListItem(id) {
  document.querySelectorAll('.muni-item').forEach(el => el.classList.remove('active'));
  const el = document.querySelector(`.muni-item[data-id="${id}"]`);
  if (el) {
    el.classList.add('active');
    el.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }
}

// ═══════════════════════════════════════════════════════════════
//  STATS
// ═══════════════════════════════════════════════════════════════

function updateStats(data) {
  document.getElementById('stat-total').textContent = data.length;
  document.getElementById('stat-cwa').textContent = data.filter(m => m.cwa_flag && m.status === 'active').length;
  document.getElementById('stat-dc').textContent = data.filter(m => m.data_center_case).length;
  document.getElementById('stat-dte').textContent = data.filter(m => m.dte_flag).length;
  document.getElementById('stat-bess').textContent = data.filter(m => m.bess_flag).length;
  document.getElementById('gap-num').textContent = data.filter(m => !m.planner_name).length;
}

// ═══════════════════════════════════════════════════════════════
//  FILTER + REFRESH
// ═══════════════════════════════════════════════════════════════

function getFilteredData() {
  const search = currentSearch.toLowerCase();
  const filtered = MUNICIPALITIES.filter(m => {
    // Firm filter
    const firmKey = m.cwa_alumni ? "CWA Alumni / In-House" : (m.firm || "Unknown");
    if (!activeFirms.has(firmKey)) return false;

    // DC only toggle
    if (showDCOnly && !m.data_center_case) return false;

    // DTE Energy builds/proposals only toggle
    if (showDTEOnly && !m.dte_flag) return false;

    // BESS (battery storage) cases only toggle
    if (showBESSOnly && !m.bess_flag) return false;

    // Search
    if (search) {
      const hay = [m.municipality, m.county, m.type, m.firm, m.planner_name, m.notes]
        .filter(Boolean).join(' ').toLowerCase();
      if (!hay.includes(search)) return false;
    }

    return true;
  });

  // Sort — alphabetical is always the tiebreaker, so "X first" sorts just
  // promote flagged entries to the top without scrambling the rest of the list.
  const byName = (a, b) => a.municipality.localeCompare(b.municipality);
  if (currentSort === 'dc') {
    filtered.sort((a, b) => (b.data_center_case - a.data_center_case) || byName(a, b));
  } else if (currentSort === 'cwa') {
    filtered.sort((a, b) => (b.cwa_flag - a.cwa_flag) || byName(a, b));
  } else {
    filtered.sort(byName);
  }

  return filtered;
}

function refreshMap() {
  const data = getFilteredData();
  drawMarkers(data);
  drawPlannerLines(data);
  if (document.getElementById('toggle-firm-lines').checked) drawFirmLines(data);
  else firmLinesLayer.clearLayers();
  buildMuniList(data);
  updateStats(data);
}

