document.getElementById('layers-panel-header').addEventListener('click', () => {
  const body = document.getElementById('layers-panel-body');
  const arrow = document.getElementById('layers-panel-arrow');
  body.classList.toggle('collapsed');
  if (body.classList.contains('collapsed')) {
    arrow.classList.replace('open', 'closed');
  } else {
    arrow.classList.replace('closed', 'open');
  }
});

document.querySelectorAll('.layer-section-header').forEach(header => {
  header.addEventListener('click', () => {
    const sectionId = header.getAttribute('data-section');
    const body = document.getElementById('body-' + sectionId);
    const arrow = document.getElementById('arrow-' + sectionId);
    body.classList.toggle('collapsed');
    arrow.classList.toggle('closed');
  });
});

function showCWAOnly() {
  // Check only CWA boxes, uncheck others
  document.querySelectorAll('#firm-filters input[type="checkbox"]').forEach(cb => {
    const firm = cb.dataset.firm;
    const isRelevant = firm && (firm.includes('Carlisle') || firm.includes('Alumni'));
    cb.checked = isRelevant;
    if (isRelevant) activeFirms.add(firm);
    else activeFirms.delete(firm);
  });
  refreshMap();
}

function showGaps() {
  currentSearch = '';
  document.getElementById('search-input').value = '';
  // Show all, highlight gaps in list (no planner_name)
  // Filter to only gaps
  activeFirms = new Set(Object.keys(FIRMS));
  document.querySelectorAll('#firm-filters input[type="checkbox"]').forEach(cb => { cb.checked = true; });
  showDCOnly = false;
  showDTEOnly = false;
  showBESSOnly = false;

  document.getElementById('toggle-dc-only').checked = false;
  document.getElementById('toggle-dte-only').checked = false;
  document.getElementById('toggle-bess-only').checked = false;
  refreshMap();
  // Flash the unknown municipalities
  MUNICIPALITIES.filter(m => !m.planner_name).forEach(m => {
    const mk = markerRefs[m.id];
    if (mk) {
      mk.setStyle({ weight: 4, color: '#f59e0b', opacity: 1 });
      setTimeout(() => mk.setStyle({ weight: m.cwa_flag ? 3 : 1.5, color: m.cwa_flag ? '#b91c1c' : getFirmColor(m) }), 3000);
    }
  });
}

// ═══════════════════════════════════════════════════════════════
//  EXPORT CSV
// ═══════════════════════════════════════════════════════════════

function downloadCSV() {
  const headers = [
    'Municipality','County','Type','Lat','Lng','Planner Name','Planner Title',
    'Firm','Employment Type','Status','CWA Flag','CWA Alumni',
    'Data Center Case','Work History','Notes','Sources','Verified','Last Updated'
  ];

  const rows = MUNICIPALITIES.map(m => [
    m.municipality, m.county, m.type, m.lat, m.lng,
    m.planner_name || '', m.planner_title || '',
    m.firm, m.employment_type || '',
    m.status, m.cwa_flag ? 'Y' : 'N', m.cwa_alumni ? 'Y' : 'N',
    m.data_center_case ? 'Y' : 'N',
    m.work_history || '',
    (m.notes || '').replace(/"/g, '""'),
    (m.sources || []).join('; '),
    'Y', LAST_UPDATED
  ]);

  // Add blank template row
  rows.push(['','','','','','','','','','unknown','N','N','N','','','','N','']);

  const csv = [headers, ...rows]
    .map(r => r.map(v => `"${String(v).replace(/"/g,'""')}"`).join(','))
    .join('\n');

  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'PACT_Michigan_Planners_' + new Date().toISOString().slice(0,10) + '.csv';
  a.click();
  URL.revokeObjectURL(url);
}

